from pysat.solvers import Glucose3

# Define the graph
edges = [
    (0,4), (0,27), (0,30), (0,34), (1,19), (1,26), (2,16), (2,17), (2,35), (3,9), (3,12), (3,25), (3,29), (3,30), (3,36), (4,15), (4,21), (4,24), (4,36), (5,10), (5,11), (5,13), (5,15), (5,17), (5,20), (5,29), (6,10), (6,17), (6,21), (7,14), (7,24), (7,25), (7,28), (7,33), (8,13), (8,26), (8,32), (8,33), (8,35), (9,12), (9,19), (9,23), (9,25), (9,30), (9,34), (10,19), (10,22), (10,31), (11,30), (11,35), (12,16), (12,17), (12,21), (12,29), (12,33), (13,15), (13,19), (13,27), (13,31), (13,32), (13,35), (14,15), (14,19), (14,22), (14,25), (14,28), (14,29), (14,32), (14,36), (15,24), (15,25), (15,28), (15,29), (15,30), (15,33), (15,35), (16,18), (16,21), (17,28), (17,35), (17,36), (18,20), (18,22), (18,36), (19,35), (20,24), (20,34), (21,25), (22,34), (23,32), (23,36), (24,28), (24,29), (24,30), (24,33), (24,34), (26,31), (26,32), (27,35), (28,33), (29,36), (30,35), (31,32), (31,36), (33,35)
]

n_vertices = 37
n_colors = 4

# Create SAT solver
solver = Glucose3()

# Variables: x[v][c] means vertex v has color c
# Variable index: v * n_colors + c + 1 (1-indexed for SAT)
def var(v, c):
    return v * n_colors + c + 1

# Each vertex must have at least one color
for v in range(n_vertices):
    solver.add_clause([var(v, c) for c in range(n_colors)])

# Each vertex can have at most one color
for v in range(n_vertices):
    for c1 in range(n_colors):
        for c2 in range(c1+1, n_colors):
            solver.add_clause([-var(v, c1), -var(v, c2)])

# Adjacent vertices must have different colors
for u, v in edges:
    for c in range(n_colors):
        solver.add_clause([-var(u, c), -var(v, c)])

# Solve
if solver.solve():
    model = solver.get_model()
    coloring = [0] * n_vertices
    for v in range(n_vertices):
        for c in range(n_colors):
            if var(v, c) in model:
                coloring[v] = c
                break
    print("SATISFIABLE")
    print(coloring)

    # Verify the solution
    valid = True
    for u, v in edges:
        if coloring[u] == coloring[v]:
            print(f"Invalid: edge ({u},{v}) has same color {coloring[u]}")
            valid = False
    if valid:
        print("Solution verified!")
else:
    print("UNSATISFIABLE")

solver.delete()
